import sys
import requests
import re
from hashlib import sha256, md5, sha1, sha3_256, sha3_512, sha3_384, blake2b, blake2s
from typing import Dict, List, Optional

def evaluate_expression(expr: str) -> int:
    try:
        return int(eval(expr))
    except:
        raise ValueError(f"Invalid expression: {expr}")

def render_template(body: str, alg_name: str) -> str:
    def replace_placeholders(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))

    rendered = re.sub(r'\{\{([^}]+)\}\}', replace_placeholders, body)
    return rendered

def compute_digest(text: str, alg_name: str) -> str:
    if alg_name == 'sha256':
        return sha256(text.encode()).hexdigest()
    elif alg_name == 'md5':
        return md5(text.encode()).hexdigest()
    elif alg_name == 'sha1':
        return sha1(text.encode()).hexdigest()
    elif alg_name == 'sha3_256':
        return sha3_256(text.encode()).hexdigest()
    elif alg_name == 'sha3_512':
        return sha3_512(text.encode()).hexdigest()
    elif alg_name == 'sha3_384':
        return sha3_384(text.encode()).hexdigest()
    elif alg_name == 'blake2b':
        return blake2b(text.encode()).hexdigest()
    elif alg_name == 'blake2s':
        return blake2s(text.encode()).hexdigest()
    else:
        raise ValueError(f"Unsupported digest algorithm: {alg_name}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python renderer.py <url>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    try:
        response = requests.get(url)
        response.raise_for_status()
        content = response.text
    except requests.RequestException as e:
        print(f"Error fetching URL: {e}", file=sys.stderr)
        sys.exit(1)

    lines = content.splitlines()
    if len(lines) < 2:
        print("Invalid template format", file=sys.stderr)
        sys.exit(1)

    digest_alg, checksum = lines[0].split()
    if digest_alg != 'alg':
        print("Invalid digest line format", file=sys.stderr)
        sys.exit(1)

    alg_name = digest_alg.split('=')[1]
    if len(lines) < 3:
        print("Invalid template format", file=sys.stderr)
        sys.exit(1)

    body = '\n'.join(lines[2:])
    rendered = render_template(body, alg_name)

    computed_checksum = compute_digest(rendered, alg_name)
    if computed_checksum == checksum:
        print(rendered, end='')
        print("OK", file=sys.stderr)
        sys.exit(0)
    else:
        print("FAIL", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

